using System.Globalization;
using System.Text.Json;
using Google.Protobuf;
using StockState = Simulation.Inventory.StockState;

static class InventoryRuntime
{
    public static void Run()
    {
        var requests = JsonSerializer.Deserialize<InventoryRequest[]>(Console.In.ReadToEnd(),
            new JsonSerializerOptions(JsonSerializerDefaults.Web)) ?? throw new JsonException("Missing requests");
        var results = requests.Select(request => {
            var entity = Simulation.Inventory.StockItem.Parser.ParseFrom(Convert.FromBase64String(request.Payload));
            var sample = new Simulation.Inventory.StockItem { Sku = request.Sku, Quantity = int.Parse(request.Quantity, CultureInfo.InvariantCulture) };
            sample.DisplayLabels.Add(request.DisplayLabels ?? Array.Empty<string>());
            var fields = new Dictionary<string, object> { ["sku"] = entity.Sku, ["quantity"] = entity.Quantity.ToString(CultureInfo.InvariantCulture) };
            if (request.DisplayLabels is not null)
                fields["display_labels"] = entity.DisplayLabels.ToArray();
            if (request.IncludeState)
                fields["state_label"] = entity.State switch {
                    StockState.Unspecified => "UNSPECIFIED",
                    StockState.Quarantined => "QUARANTINED",
                    _ => "UNKNOWN",
                };
            return new { fields, in_stock = entity.Quantity > 0 && entity.State == Simulation.Inventory.StockState.Unspecified, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };
        });
        Console.WriteLine(JsonSerializer.Serialize(results));
    }
}
record InventoryRequest(string Payload, string Sku, string Quantity, [property: System.Text.Json.Serialization.JsonPropertyName("display_labels")] string[]? DisplayLabels,
    [property: System.Text.Json.Serialization.JsonPropertyName("include_state")] bool IncludeState = false);

"""Stock producer/consumer; JSON quantities are canonical decimal strings."""
import base64
import json
import sys
from inventory.item_pb2 import STOCK_STATE_QUARANTINED, STOCK_STATE_UNSPECIFIED, StockItem


def evaluate(request):
    entity = StockItem.FromString(base64.b64decode(request['payload'], validate=True))
    sample = StockItem(sku=request['sku'], quantity=int(request['quantity']),
                       display_labels=request.get('display_labels', []))
    fields = {'sku': entity.sku, 'quantity': str(entity.quantity)}
    if 'display_labels' in request:
        fields['display_labels'] = list(entity.display_labels)
    if request.get('include_state'):
        fields['state_label'] = {
            STOCK_STATE_UNSPECIFIED: 'UNSPECIFIED',
            STOCK_STATE_QUARANTINED: 'QUARANTINED',
        }.get(entity.state, 'UNKNOWN')
    return {'fields': fields, 'in_stock': entity.quantity > 0 and entity.state == STOCK_STATE_UNSPECIFIED,
            'constructed_payload': base64.b64encode(sample.SerializeToString()).decode()}


def run():
    print(json.dumps([evaluate(request) for request in json.load(sys.stdin)]))

import { readFileSync } from "node:fs";
import { StockItem, StockState } from "../../generated/ts/inventory/item";

interface Request { payload: string; sku: string; quantity: string; display_labels?: string[]; include_state?: boolean }
function stateLabel(state: StockState) {
  switch (state) {
    case StockState.STOCK_STATE_UNSPECIFIED: return "UNSPECIFIED";
    case StockState.STOCK_STATE_QUARANTINED: return "QUARANTINED";
    default: return "UNKNOWN";
  }
}
export function runInventory() {
  const requests: Request[] = JSON.parse(readFileSync(0, "utf8"));
  const results = requests.map(request => {
    const entity = StockItem.decode(new Uint8Array(Buffer.from(request.payload, "base64")));
    const sample = StockItem.encode({ sku: request.sku, quantity: Number.parseInt(request.quantity, 10), state: StockState.STOCK_STATE_UNSPECIFIED,
      displayLabels: request.display_labels ?? [] }).finish();
    const fields = {
      sku: entity.sku, quantity: entity.quantity.toString(),
      ...(request.display_labels === undefined ? {} : { display_labels: entity.displayLabels }),
      ...(request.include_state ? { state_label: stateLabel(entity.state) } : {}),
    };
    return { fields, in_stock: BigInt(entity.quantity) > 0n && entity.state === StockState.STOCK_STATE_UNSPECIFIED, constructed_payload: Buffer.from(sample).toString("base64") };
  });
  console.log(JSON.stringify(results));
}
